import 'package:flutter/material.dart';
import '../../core/models/duplicate_file.dart';
import '../../core/mock/mock_data.dart';
import 'deletion_progress_screen.dart';
class DeleteConfirmationScreen extends StatelessWidget { final List<DuplicateFile> selectedFiles; const DeleteConfirmationScreen({super.key,required this.selectedFiles}); int get totalBytes=>selectedFiles.fold(0,(s,f)=>s+f.size);
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Confirm deletion')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[const SizedBox(height:18),Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:Theme.of(c).colorScheme.errorContainer,shape:BoxShape.circle),child:const Icon(Icons.delete_forever_rounded,size:46)),const SizedBox(height:22),const Text('Delete selected files?',style:TextStyle(fontSize:25,fontWeight:FontWeight.w800)),const SizedBox(height:10),Text('${selectedFiles.length} files • ${MockData.formatBytes(totalBytes)}',style:const TextStyle(fontSize:16,fontWeight:FontWeight.w700)),const SizedBox(height:14),const Text('The selected files will be permanently removed from storage. This action cannot be undone.',textAlign:TextAlign.center,style:TextStyle(color:Colors.black54)),const Spacer(),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel'))),const SizedBox(width:12),Expanded(child:FilledButton(onPressed:selectedFiles.isEmpty?null:()=>Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>DeletionProgressScreen(selectedFiles:selectedFiles))),child:const Text('Delete Files')))])])));
}
